{"files": {"/root/hp/tools/genprobs.py": "# Generate a --load-transformer-probs file (float16, V=205 per row) for tokens [A, B)
# of the post-WRT stream, reproducing predictor.cpp TransformerByteUpdate semantics:
#   row k (k in [A,B)) = distribution for token k+1;
#   if token k is the last token of its piece (article chunk end or 2^17 cut) -> PPMD prior row k
#   else -> transformer softmax output at token k (full in-piece context, as in a full run).
# Also writes the bytes slice (vocab[tok[A:B]]) for the lab compressor.
# usage: python genprobs.py A B out_prefix [ckpt]
import sys, numpy as np, torch
sys.path.insert(0, '/root/hp/tools')
import tfh

A, B, out = int(sys.argv[1]), int(sys.argv[2]), sys.argv[3]
ckpt = sys.argv[4] if len(sys.argv) > 4 else tfh.REPO + '/models/6m-q4-fp32.tch'
data = tfh.Data()
vocab = np.fromfile('/root/hp/data/vocab.list', dtype=np.uint8)
assert B <= len(data.cnt), 'priors not yet available for this range'
model = tfh.load_model(ckpt)
dev = 'cuda'
V = 205
probs = np.zeros((B - A, V), dtype=np.float16)
filled = np.zeros(B - A, dtype=bool)
b = data.bounds
a0 = int(np.searchsorted(b, A, side='right') - 1)
a1 = int(np.searchsorted(b, B - 1, side='right') - 1)

def prior_rows(lo, hi):
    """dense prior rows lo..hi-1 as float32"""
    c = np.asarray(data.cnt[lo:hi], dtype=np.int64)
    # entry offset of row lo: article offset + partial sum
    a = int(np.searchsorted(b, lo, side='right') - 1)
    off = int(data.boff[a]) + int(np.asarray(data.cnt[b[a]:lo], dtype=np.int64).sum())
    n = int(c.sum())
    ii = np.asarray(data.idx[off:off + n], dtype=np.int64)
    vv = np.asarray(data.val[off:off + n], dtype=np.float32)
    P = np.zeros((hi - lo, V), np.float32)
    P[np.repeat(np.arange(hi - lo), c), ii] = vv
    return P

with torch.no_grad():
    batch = []; blen = 0
    def flush():
        global batch, blen
        if not batch: return
        toks = np.concatenate([x[1] for x in batch]); pri = np.concatenate([x[2] for x in batch])
        cu = np.cumsum([0] + [len(x[1]) for x in batch]).astype(np.int32)
        lg = model.compute_logits(torch.from_numpy(toks).to(dev)[None], torch.from_numpy(pri).to(dev)[None],
                                  torch.from_numpy(cu).to(dev)[None])[0].float()
        pr = torch.softmax(lg, -1).to(torch.float16).cpu().numpy()
        for i, (gs, t, _) in enumerate(batch):
            s, e = int(cu[i]), int(cu[i + 1])
            # rows gs .. gs+L-2 come from transformer positions 0..L-2
            for_rows = np.arange(gs, gs + (e - s) - 1)
            sel = (for_rows >= A) & (for_rows < B)
            probs[for_rows[sel] - A] = pr[s:e - 1][sel]
            filled[for_rows[sel] - A] = True
        batch = []; blen = 0
    for a in range(a0, a1 + 1):
        s, e = int(b[a]), int(b[a + 1])
        t = np.asarray(data.tok[s:e], dtype=np.int64)
        P = prior_rows(s, e)
        for (ps, pe) in tfh.pieces_of(e - s):
            if pe - ps >= 2 and (s + pe - 2) >= A and (s + ps) < B:
                if blen + (pe - ps) > (1 << 17):
                    flush()
                batch.append((s + ps, t[ps:pe], P[ps:pe])); blen += pe - ps
            # last token of the piece -> PPMD prior row
            k = s + pe - 1
            if A <= k < B:
                probs[k - A] = P[pe - 1].astype(np.float16); filled[k - A] = True
    flush()
assert filled.all(), f'unfilled rows: {(~filled).sum()}'
probs.tofile(out + '.probs.f16')
vocab[np.asarray(data.tok[A:B])].tofile(out + '.bin')
print('wrote', out, B - A)
", "/root/hp/tools/revan.py": "# Analyse PHDA9 revision records in the tail: fields, and how predictable revision ids are from
# timestamps given the previously coded records (decoder-side, causal).
import re, math, bisect, collections, numpy as np
data = open('/root/hp/gen/.main_phda9prepr', 'rb').read()
i = data.rfind(b'</page>') + 8
tail = data[i:]
lines = tail.split(b'\n')
recs = []
j = 0
while j < len(lines) and not lines[j].startswith(b'revision>'): j += 1
first = j
kinds = collections.Counter()
while j < len(lines):
    if not lines[j].startswith(b'revision>'):
        break
    r = {'extra': [], 'other': []}
    j += 1
    while j < len(lines) and not lines[j].startswith(b'revision>'):
        L = lines[j]
        if L.startswith(b'[') or L.startswith(b'{') or b'</text' in L: break
        if L.startswith(b'id>') and 'revid' not in r: r['revid'] = int(L[3:])
        elif L.startswith(b'timestamp>'): r['ts'] = L[10:].decode()
        elif L.startswith(b'username>'): r['user'] = L[9:]
        elif L.startswith(b'id>'): r['uid'] = int(L[3:])
        elif L.startswith(b'ip>'): r['ip'] = L[3:]
        elif L in (b'contributor>', b'/contributor>'): pass
        elif L.startswith(b'>'): r['extra'].append(L)
        else: r['other'].append(L); kinds[L.split(b'>')[0]] += 1
        j += 1
    recs.append(r)
    if j < len(lines) and not lines[j].startswith(b'revision>'): break
print('records', len(recs), 'stopped at line', j, 'of', len(lines), repr(lines[j][:80]) if j < len(lines) else '')
print('other field kinds', kinds.most_common(10))
rec_bytes = sum(len(l) + 1 for l in lines[first:j])
print('record region bytes', rec_bytes, 'remaining tail bytes', len(tail) - rec_bytes)
ex = collections.Counter(len(r['extra']) for r in recs)
print('extra-line counts', ex.most_common(5))
recs = [r for r in recs if 'revid' in r and 'ts' in r]
# timestamp format day:sec ; parse
def ts2s(t):
    d, s = t.split(':'); return int(d) * 86400 + int(s)
T = np.array([ts2s(r['ts']) for r in recs], dtype=np.int64)
R = np.array([r['revid'] for r in recs], dtype=np.int64)
print('ts range', T.min(), T.max(), 'revid range', R.min(), R.max())
# monotonicity check: correlation of rank
ordT = np.argsort(T, kind='stable'); inv = R[ordT]
print('fraction of adjacent (by time) pairs with increasing revid:', np.mean(np.diff(inv) > 0))
# causal predictor: for record k, predict revid from timestamp using previously seen records:
# find neighbours in time among seen records (sorted list), linear interpolation.
seenT = []; seenR = []
res = []
for k in range(len(recs)):
    t, r = int(T[k]), int(R[k])
    if len(seenT) >= 2:
        p = bisect.bisect_left(seenT, t)
        lo = max(0, p - 1); hi = min(len(seenT) - 1, p)
        if lo == hi:
            if hi == 0: lo, hi = 0, 1
            else: lo, hi = hi - 1, hi
        t0, t1, r0, r1 = seenT[lo], seenT[hi], seenR[lo], seenR[hi]
        pred = r0 if t1 == t0 else r0 + (r1 - r0) * (t - t0) / (t1 - t0)
        res.append(r - pred)
    p = bisect.bisect_left(seenT, t)
    seenT.insert(p, t); seenR.insert(p, r)
res = np.array(res)
a = np.abs(res)
for q in [50, 75, 90, 95, 99]:
    print(f'|revid residual| p{q} = {np.percentile(a, q):.0f}')
# entropy estimate of residual with Elias-gamma-like / log2 cost
est = np.mean(np.log2(a + 1) * 1.0 + 2.0)
print('approx bits per revid with interpolation coding ~', est, ' vs raw digits ~', np.mean(np.log2(R)))
# timestamp predictability from revid (reverse)
users = collections.Counter(r.get('user') for r in recs if 'user' in r)
print('distinct users', len(users), 'records with user', sum(users.values()), 'ip records', sum(1 for r in recs if 'ip' in r))
# uid determinism: is uid a function of user?
m = {}; bad = 0
for r in recs:
    if 'user' in r:
        if r['user'] in m and m[r['user']] != r['uid']: bad += 1
        m[r['user']] = r['uid']
print('user->uid violations', bad)
first_seen = sum(1 for u in users)  # each user's first appearance needs its uid coded
print('records whose user was seen before (uid predictable):', sum(users.values()) - len(users))
", "/root/hp/tools/iw_stats.py": "# Interwiki statistics on original enwik9: how often does an interlanguage link title
# equal (or nearly equal) the English article title?
import re, collections, unicodedata
data = open('/root/hp/data/enwik9', 'rb').read().decode('utf-8', errors='replace')
pages = data.split('<page>')[1:]
iw_re = re.compile(r'^\[\[([a-z][a-z\-]{1,11}):([^\]\n]*)\]\]\s*$')
n_pages = n_with = n_ent = 0
eq = eq_ci = eq_strip = 0
bytes_ent = bytes_eq = 0
langs = collections.Counter()
per_block = []
def strip_acc(s):
    return ''.join(c for c in unicodedata.normalize('NFKD', s) if not unicodedata.combining(c)).lower()
for p in pages:
    n_pages += 1
    t0 = p.find('<title>'); t1 = p.find('</title>')
    title = p[t0 + 7:t1]
    s = p.find('<text xml:space="preserve">'); e = p.find('</text>')
    if s < 0 or e < 0: continue
    lines = p[s:e].split('\n')
    ents = []
    for ln in reversed(lines):
        m = iw_re.match(ln.strip())
        if m: ents.append((m.group(1), m.group(2)))
        elif ln.strip() == '': continue
        else: break
    if not ents: continue
    n_with += 1
    k = 0
    for lang, tt in ents:
        n_ent += 1; langs[lang] += 1
        L = len(lang) + len(tt) + 6
        bytes_ent += L
        if tt == title: eq += 1; bytes_eq += L; k += 1
        elif tt.lower() == title.lower(): eq_ci += 1
        elif strip_acc(tt) == strip_acc(title): eq_strip += 1
    per_block.append((len(ents), k))
print('pages', n_pages, 'pages with interwiki', n_with, 'entries', n_ent)
print('exact title copies', eq, f'{eq/n_ent:.3f}', 'case-insens extra', eq_ci, 'accent-strip extra', eq_strip)
print('entry bytes', bytes_ent, 'bytes in exact copies', bytes_eq)
blocks_with_copy = sum(1 for n, k in per_block if k > 0)
print('blocks with >=1 exact copy', blocks_with_copy)
print('top langs', langs.most_common(25))
